package com.qwerty.homenet.sht;
import java.util.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.core.BlockPos;
import com.qwerty.homenet.network.*;
import net.minecraftforge.client.event.ScreenEvent;
import net.minecraftforge.common.MinecraftForge;
import org.lwjgl.glfw.GLFW;
final class HelpProbe {
 static void check(boolean b,String m){ClientRun.check(b,m);}
 static void open(Screen s){var state=UsageHelp.state(s);check(state!=null,"Missing usage button: "+s.getClass());var e=new ScreenEvent.MouseButtonPressed.Pre(s,state.button.getX()+4,state.button.getY()+4,0);MinecraftForge.EVENT_BUS.post(e);check(e.isCanceled()&&UsageHelp.active(s),"Help click fell through");var g=new GuiGraphics(Minecraft.getInstance(),Minecraft.getInstance().renderBuffers().bufferSource());MinecraftForge.EVENT_BUS.post(new ScreenEvent.Render.Post(s,g,0,0,0));g.flush();check(state.lines.size()>4,"Help text missing");}
 static void verify(Screen s){var mc=Minecraft.getInstance();mc.setScreen(s);open(s);var st=UsageHelp.state(s);var scroll=new ScreenEvent.KeyPressed.Pre(s,GLFW.GLFW_KEY_END,0,0);MinecraftForge.EVENT_BUS.post(scroll);check(scroll.isCanceled()&&st.scroll==st.max,"Help scroll did not reach end");var digit=new ScreenEvent.CharacterTyped.Pre(s,'1',0);MinecraftForge.EVENT_BUS.post(digit);check(digit.isCanceled(),"Help dial key leaked");var click=new ScreenEvent.MouseButtonPressed.Pre(s,s.width/2,s.height/2,0);MinecraftForge.EVENT_BUS.post(click);check(click.isCanceled(),"Help click reached product");s.resize(mc,320,240);check(UsageHelp.active(s),"Resize closed help");var esc=new ScreenEvent.KeyPressed.Pre(s,GLFW.GLFW_KEY_ESCAPE,0,0);MinecraftForge.EVENT_BUS.post(esc);check(esc.isCanceled()&&!UsageHelp.active(s)&&mc.screen==s,"Help did not return to same live controller");s.resize(mc,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight());}
 static void selectedModels(){var mc=Minecraft.getInstance();for(var pos:VideoProbe.positions){if(!(mc.level.getBlockEntity(pos) instanceof com.qwerty.homenet.blockentity.Kvm906BlockEntity b))continue;var d=new WallpadDataPacket(pos,false,0,"101-1001",false,0,"",false,"","",List.of(),List.of(),List.of(),List.of(),Map.of(),new long[15],List.of());var screen=new com.qwerty.homenet.client.kvm.Kvm906Screen(d);check(UsageText.title(screen).equals(b.design().model().label()),"Selected model title mismatch");check(String.join(" ",UsageText.forScreen(screen)).contains(b.design().model().label()),"Selected model guide mismatch");verify(screen);}mc.setScreen(null);System.out.println("SELECTED_MODEL_HELP_PASS: actual client block entities choose each KVM model guide");}
 static void catalogue(){var mc=Minecraft.getInstance();var pos=new BlockPos(9999,60,9999);var d=new WallpadDataPacket(pos,false,0,"101-1001",false,0,"",false,"","",List.of(),List.of(),List.of(),List.of(),Map.of(),new long[15],List.of());
  List<Screen> screens=List.of(new Controls(d,false),new Controls(d,true),new PortableControls(d),new AddressControls(pos,"101-1001"),new com.qwerty.homenet.client.WallpadScreen(d),new com.qwerty.homenet.client.DoorStationScreen(new DoorStationDataPacket(pos,false,false,"101-1001",0,"",false,false,List.of())),new com.qwerty.homenet.client.am.Am10kpScreen(d),new com.qwerty.homenet.client.kam.Kam305Screen(d),new com.qwerty.homenet.client.guard.GuardMasterScreen(d),new com.qwerty.homenet.client.ha.Ha4100hConfigScreen(d),new com.qwerty.homenet.client.hmc.Hmc7000Screen(d),new com.qwerty.homenet.client.ipap.Ip203apScreen(d),new com.qwerty.homenet.client.klp.Klp203rfScreen(d),new com.qwerty.homenet.client.kvm.Kvm906Screen(d),new com.qwerty.homenet.client.lobby.LobbyPhoneScreen(pos),new com.qwerty.homenet.client.wallpad.KhnWallpadScreen(d),new com.qwerty.homenet.client.DeviceConfigScreen(new DeviceConfigOpenPacket(pos,"조명",0,false)));
  for(var s:screens)verify(s);
  for(var m:com.qwerty.homenet.kvm.KvmModel.values()){var text=new ArrayList<String>();UsageText.kvmText(m,text);check(text.get(0).contains(m.label()),"Wrong selected KVM help");for(String key:m.keys)check(text.stream().anyMatch(t->t.contains(m.keyLabel(key))),"Missing model key "+m+":"+key);}
  var wired=new HashMap<String,String>();wired.put("wired","1");var wd=new WallpadDataPacket(pos,false,0,"101-1001",false,0,"",false,"","",List.of(),List.of(),List.of(),List.of(),wired,new long[15],List.of());var s=new Controls(wd,false);verify(s);check(String.join(" ",UsageText.forScreen(s)).contains("별도 문열림 버튼이 없습니다"),"102 door release instruction incorrect");
  mc.setScreen(null);System.out.println("ALL_MODEL_HELP_CLIENT_PASS: 18 operation controllers, all 13 KVM capability variants, real event bus button/input/render, scroll, resize and Esc return; no screenshots");
 }
}
